Ethernet II frame as it appears on the wire (sizes in bytes)

 7         1     6        6        2          46..1500      4      12
+---------+-----+--------+--------+----------+-------------+-----+-------+
|Preamble | SFD | Dst MAC| Src MAC| EtherType|   Payload   | FCS |  IPG  |
|AA x7    | AB  |        |        |          | (padded)    |     | (idle)|
+---------+-----+--------+--------+----------+-------------+-----+-------+
          |<--------- frame: 64 to 1518 bytes -------------->|

Worked example: ARP request, 42 bytes of real content, padded to 64
 dst  ff:ff:ff:ff:ff:ff     src  3c:22:fb:10:9a:07
 type 08 06 (ARP)           payload = 28-byte ARP + 18 bytes zero pad
 frame = 14 + 46 + 4 = 64 bytes; on the wire = 64 + 8 + 12 = 84 bytes

/* Classify a destination MAC (6 bytes, as received) */
#include <stdint.h>
#include <string.h>

static const uint8_t BCAST[6] = {0xff,0xff,0xff,0xff,0xff,0xff};

int is_broadcast(const uint8_t m[6]) { return memcmp(m, BCAST, 6) == 0; }
int is_group(const uint8_t m[6])     { return m[0] & 0x01; }  /* I/G bit */
int is_local_admin(const uint8_t m[6]) { return (m[0] & 0x02) != 0; } /* U/L */

/* IPv4 multicast group -> MAC: 01:00:5e + low 23 bits of the group */
void mcast_mac4(uint32_t group_host_order, uint8_t m[6]) {
    m[0] = 0x01; m[1] = 0x00; m[2] = 0x5e;
    m[3] = (group_host_order >> 16) & 0x7f;
    m[4] = (group_host_order >> 8) & 0xff;
    m[5] = group_host_order & 0xff;
}
